// Design-token pipeline check (Designer's build.py + check_contrast.py, PM decision #31).
// 1. Rebuilds tokens.css / theme.css / tailwind.preset.js from tokens.json in a temp copy and
//    fails if the committed files differ (generated files must never be hand-edited).
// 2. Runs check_contrast.py (WCAG ratios + PM #31 pairing rules); fails on any unhandled failure.
//    Also fails if the committed contrast-report.md is stale (ignoring its date line).
// Needs python3 (no network, no pip packages). Leaves the repo untouched.
import { execFileSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const src = new URL('../packages/ui/tokens/', import.meta.url).pathname;
// check_contrast.py verifies tokens.json against SPEC Sec 8.2 when it can find the spec.
const spec = new URL('../docs/SPEC.md', import.meta.url).pathname;
const env = { ...process.env, DASIG_SPEC: process.env.DASIG_SPEC ?? spec };
const tmp = mkdtempSync(join(tmpdir(), 'dasig-tokens-'));
const GENERATED = ['tokens.css', 'theme.css', 'tailwind.preset.js'];
let failed = false;

const run = (script) => {
  try {
    const out = execFileSync('python3', [script], { cwd: tmp, encoding: 'utf8', env });
    process.stdout.write(out);
    return true;
  } catch (err) {
    process.stdout.write(String(err.stdout ?? ''));
    process.stderr.write(String(err.stderr ?? err));
    return false;
  }
};

try {
  cpSync(src, tmp, { recursive: true });
  console.log('> python3 build.py');
  if (!run('build.py')) failed = true;
  for (const file of GENERATED) {
    const same = readFileSync(join(src, file), 'utf8') === readFileSync(join(tmp, file), 'utf8');
    console.log(
      `${same ? 'ok  ' : 'FAIL'} ${file} ${same ? 'matches' : 'differs from'} build.py output`,
    );
    if (!same) failed = true;
  }
  console.log('> python3 check_contrast.py');
  if (!run('check_contrast.py')) failed = true;
  const strip = (s) => s.replace(/^Generated by .*$/m, '');
  const fresh =
    strip(readFileSync(join(src, 'contrast-report.md'), 'utf8')) ===
    strip(readFileSync(join(tmp, 'contrast-report.md'), 'utf8'));
  console.log(`${fresh ? 'ok  ' : 'FAIL'} contrast-report.md is ${fresh ? 'up to date' : 'stale'}`);
  if (!fresh) failed = true;
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
if (failed) {
  console.error(
    'Design-token check failed. Regenerate in packages/ui/tokens: python3 build.py && python3 check_contrast.py',
  );
  process.exit(1);
}
console.log('Design tokens: generated files in sync, contrast check passed.');
